CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS fleet_catalog (id text PRIMARY KEY, make text NOT NULL, model text NOT NULL, year integer NOT NULL, category text NOT NULL, transmission text, fuel_type text, base_daily_rate numeric(10,2) NOT NULL, vehicles_available integer NOT NULL, location text);
CREATE TABLE IF NOT EXISTS customer_profiles (id text PRIMARY KEY, full_name text NOT NULL, birth_date date NOT NULL, license_number text, license_issue_date date NOT NULL, license_exp_date date NOT NULL, risk_category text);
CREATE TABLE IF NOT EXISTS booking_logs (id text PRIMARY KEY, customer_id text, vehicle_id text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, days integer NOT NULL, insurance_option text, deposit_amount numeric(10,2), discount_code text, seasonal_multiplier numeric(4,2), status text DEFAULT 'CONFIRMED');
CREATE TABLE IF NOT EXISTS seasonal_pricing_matrix (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month integer NOT NULL, category text NOT NULL, multiplier numeric(4,2) NOT NULL);
CREATE TABLE IF NOT EXISTS rental_policies_vectors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content text NOT NULL, source text NOT NULL, embedding vector(1536) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS rental_policies_vectors_embedding_idx ON rental_policies_vectors USING ivfflat (embedding vector_cosine_ops) WITH (lists = 100);
CREATE TABLE IF NOT EXISTS agent_requests (id text PRIMARY KEY, state jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS checkpoints (thread_id text NOT NULL, checkpoint_ns text NOT NULL DEFAULT '', checkpoint_id text NOT NULL, parent_checkpoint_id text, type text, checkpoint jsonb NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(thread_id,checkpoint_ns,checkpoint_id));
CREATE TABLE IF NOT EXISTS checkpoint_writes (thread_id text NOT NULL, checkpoint_ns text NOT NULL DEFAULT '', checkpoint_id text NOT NULL, task_id text NOT NULL, idx integer NOT NULL, channel text NOT NULL, type text, value jsonb, PRIMARY KEY(thread_id,checkpoint_ns,checkpoint_id,task_id,idx));
CREATE TABLE IF NOT EXISTS checkpoint_blobs (thread_id text NOT NULL, checkpoint_ns text NOT NULL DEFAULT '', channel text NOT NULL, version text NOT NULL, type text NOT NULL, blob bytea, PRIMARY KEY(thread_id,checkpoint_ns,channel,version));
